rows=[]
def add(i,url,title,pub,version,file,section,pop,limits,note,level='section'):
 p=Path(file);p=p if p.is_absolute() else C/p
 assert p.is_file(),p
 rows.append(dict(id=i,url=url,titre=title,editeur=pub,version_annee=version,date_consultation='2026-11-02',section_page=section,population=pop,limites=limits,cache_external=str(p),sha256=hashlib.sha256(p.read_bytes()).hexdigest(),lecteur='sol_endocrinologie',read_level=level,passage_paraphrase=note))
add('S1','https://dam-api.bfs.admin.ch/hub/api/dam/assets/32686265/master','CIM-10-GM E32 et subdivisions','OFS Suisse','2024',R/'nosology/fragments/S05.json','Entrées locales E32, E32.0, E32.1, E32.8, E32.9','Classification suisse','Libellés locaux 2024 ; pas certification du codage individuel 2026.','E32 couvre les maladies thymiques non précisées ailleurs ; hyperplasie persistante, abcès et autres maladies sont distingués. La classification ne prescrit pas le traitement.')
add('S2','https://klassifikationen.bfarm.de/icd-10-gm/kode-suche/htmlgm2024/block-e20-e35.htm','Notes CIM-10-GM E32','BfArM Allemagne','2024','bfarm2024.html','E32 et sous-codes, exclusions D82.1 et G70.0','Classification allemande','Notes allemandes confrontées aux libellés suisses ; pas assimilation de toutes masses médiastinales à E32.','Aplasie/hypoplasie avec immunodéficience et myasthénie sont exclues. Les tumeurs gardent leurs codes propres ; kyste non tumoral discuté dans autre affection précisée.')
add('S3','https://pmc.ncbi.nlm.nih.gov/articles/PMC12784861/','Thymic Hyperplasias in Practice: Clinical Context, Histological Clues, and Management Implications','Stefan Porubsky, Mainz Allemagne ; Cancers','Publié27 décembre2025, volume18 janvier2026','porubsky2025.html','Introduction, méthodes, sections3.1–3.4, conclusions, tableaux1–4 et figures1–5','Hyperplasies thymiques humaines','L’abstract parle systématique mais méthodes précisent revue narrative ; un auteur et données hétérogènes. L’absence de lien intrinsèque auto-immun des formes vraies ne nie pas leur association avec Basedow.','Architecture conservée vraie/rebond, follicules lymphoïdes parfois sans gros thymus, forme lymphoépithéliale distincte. Série36cas de cette dernière :33%auto-immunité non myasthénique et14%lymphome associés, pas risque prospectif. Poids autopsiques anciens ne sont pas seuils de scanner. Suivi après exérèse complète bénigne distinct du suivi de la cause.')
base='https://richtlijnendatabase.nl/richtlijn/epitheliale_thymustumoren/diagnostiek_epitheliae_thymustumoren/'
add('S4',base+'beeldvormende_diagnostiek_voor_pati_nten_met_een_verdenking_op_een_thymustumor.html','Imagerie devant suspicion de tumeur thymique','NVALT / Fédération des spécialistes, Pays-Bas','8novembre2024, validité revue31août2024','nvalt-imaging2024.html','Recommandations et Overwegingen, forces/limites, indications de tomographie et IRM','Suspicion adulte de tumeur et découvertes fortuites','Recommandation européenne pour diagnostic différentiel, pas protocole pédiatrique universel. Preuves faibles ; références NCCN citées par groupe européen, pas guideline américaine directement lue ni seule fondation.','Scanner injecté si suspicion solide, IRM si kyste/hyperplasie incertaine, pas tomographie par émission de positons systématique. Kyste simple certain ou hyperplasie certaine en IRM : pas suivi spécifique selon ce module. Chez jeune sans graisse les séquences en/opposition de phase ne sont pas utilisables de façon identique.')
add('S5',base+'biopt_bij_epitheliale_thymustumoren.html','Place de la biopsie dans les tumeurs épithéliales thymiques','NVALT Pays-Bas','8novembre2024','nvalt-biopsy2024.html','Recommandations, arguments et absence de comparaison directe des techniques','Suspicion de tumeur épithéliale','Ne pas appliquer le schéma tumeur résécable à tout diagnostic médiastinal, notamment lymphome ou infection.','Pas de biopsie d’une tumeur épithéliale présumée résécable après discussion experte ; biopsie histologique si non résécable. Résécabilité décidée en équipe, pas sur un diamètre arbitraire.')
add('S6',base+'lab-analyses_voor_vaststellen_paraneoplastische_syndromen.html','Analyses pour syndromes paranéoplasiques','NVALT Pays-Bas','8novembre2024','nvalt-biology2024.html','Recommandations, rationale et absence de preuve comparative','Adultes avec suspicion de tumeur épithéliale','Mesures d’experts ; ne pas dépister tous les anticorps chez tout thymus physiologique.','Recherche d’anticorps du récepteur de l’acétylcholine chez suspicion tumorale ; immunoglobulines/profil lymphocytaire si infections récidivantes et réticulocytes si anémie. Tableau clinique guide l’urgence neurologique.')
add('S7','https://pmc.ncbi.nlm.nih.gov/articles/PMC12774464/','Optimizing Diagnosis and Surgery for Pure Anterior Mediastinal Cysts: Insights from a Single-Centre Study','Rieg et coll., Toulouse France','2025','francecysts2025.xml','Méthodes, résultats, discussion et limites ; tableaux1–3','70patients sélectionnés en réunion spécialisée2012–2025,26opérés','Rétrospective monocentrique, vérification histologique sélective, très larges intervalles ; inclut tératomes matures dans groupe néoplasique. Proposition PET initial contredit approche NVALT, pas nouveau standard européen.','Parmi26opérés,8lésions néoplasiques/potentiellement malignes dont4thymomes et4germinales, avec3tératomes matures ; pas30,8%de tous kystes cancéreux.26kystes typiques non opérés sans progression au suivi moyen26,1mois. Surveillance locale annuelle deux ans puis quatrième année, pas intervalle universel.')
for i,k,url,version,pop,limit,note in [
 ('S8','btog2024','https://pubmed.ncbi.nlm.nih.gov/38565483/','2024','Proposition britannique multidisciplinaire','Résumé seul ; aucun détail d’algorithme ou intervalle attribué sans lecture.','L’algorithme vise à éviter résections bénignes et surveillance inutile ; IRM selon indication et expertise.'),
 ('S9','priola2014','https://pubmed.ncbi.nlm.nih.gov/25105246/','En ligne2014, volume2015','92adultes18–84ans,30hyperplasies et62tumeurs, Italie','Résumé seul, monocentrique ; seuils optimisés sur cette série, pas règle pédiatrique ni garantie100%.','Indice d’intensité à8,92% distinguait groupes dans cette série ; rapport déplacement chimique chevauche chez adultes jeunes, limites âge et méthode explicites.'),
 ('S10','inaoka2007','https://pubmed.ncbi.nlm.nih.gov/17463136/','2007','41patients16–78ans, Japon','Résumé seul, petite série hors Europe, confirmation technique et non fondation clinique unique.','23hyperplasies dont18Basedow avaient baisse de signal,18tumeurs non ; ces résultats ne rendent pas toute absence de baisse maligne.'),
 ('S11','franke2023','https://pubmed.ncbi.nlm.nih.gov/37243889/','2023','291enfants Hodgkin EuroNet-PHL-C1 avec imagerie adéquate','Résumé seul ;98des133grossissements classés, critères non validés chez tout patient.','133/291croissances ;64/64rebonds isolés,33/34rechutes avec autres masses croissantes. Aucune caractéristique thymique seule discriminante, une rechute isolée restait possible.'),
 ('S12','dallacosta2014','https://pubmed.ncbi.nlm.nih.gov/25149085/','En ligne2014, volume2015','Cas et107cas publiés Basedow','Résumé seul, biais de publication et sélection, pas incidence ni risque4/107généralisable.','Mécanismes hormonaux et immunitaires proposés ; régression peut se produire malgré anticorps persistants. Ne pas prouver mécanisme par simple association.'),
 ('S15','abscess2008','https://pubmed.ncbi.nlm.nih.gov/18480581/','2008','Une femme64ans, Japon','Résumé de cas isolé, pas protocole antibiotique ni sensibilité de marqueur.','Abcès rompu dans plèvre, exérèse et histologie ; élévation du marqueur CA-125 non preuve de cancer.'),
 ('S16','abscess1993','https://pubmed.ncbi.nlm.nih.gov/8449107/','1993','Un sujet gériatrique','Résumé de cas isolé, littérature ancienne ; antibiotique et dose non lus.','Douleur rétrosternale initialement coronarienne, bactériémie Staphylococcus aureus, abcès et atteinte manubriosternale ; penser infection sans exclure d’abord urgence cardiaque.'),
 ('S21','detection2025','https://pubmed.ncbi.nlm.nih.gov/39657307/','2025','75experts24pays, enquête initiée Pays-Bas/ITMIG/RYTHMIC','Résumé seul ; enquête de pratiques et non recommandation consensuelle validée.','Forte variation des examens, chirurgie et suivi ; le nom Delphi ne démontre pas un consensus de conduite.'),
 ('S22','mayhew2024','https://pubmed.ncbi.nlm.nih.gov/39294035/','2024','96patients avec diagnostic radiologique retenu de kyste, Royaume-Uni','Résumé seul, sélection sur diagnostic et suivis variables ; dix ans désignent période de recherche, pas dix ans pour chacun.','Aucune malignité observée pendant surveillance ; variations de taille et contenu possibles. Une fois kyste simple caractérisé par IRM, surveillance prolongée peut être inutile.')]:
 r=json.loads((C/(k+'-meta.json')).read_text())['resultList']['result'][0]
 add(i,url,r['title'],r.get('authorString','Auteurs publiés'),version,k+'-meta.json','Résumé publié',pop,limit,note,'abstract')
add('S13','https://pmc.ncbi.nlm.nih.gov/articles/PMC10580497/','Thymic Hyperplasia and Graves Disease: A Nonincidental Association','Pla Peris et coll., Castellón Espagne','2023','graves2023xml.xml','Deux cas, discussion mécanismes et suivi, points pédagogiques','Deux hommes55et40ans avec Basedow','Publication de cas européenne dans revue américaine ; preuve faible. Expressions générales de bénignité ne permettent pas d’exclure tumeur chez tout Basedow. Pas transposition méthimazole en dose carbimazole.','Un patient opéré, un autre régression après euthyroïdie au scanner douze mois ; suivre cause et réévaluer critères suspects ou absence de régression, délai individualisé.')
add('S14','https://pmc.ncbi.nlm.nih.gov/articles/PMC9792833/','Mediastinal thymic cysts: a narrative review','Cooley-Rieders et Van Haren, Cincinnati États-Unis','2022','cysts2022.html','Embryologie, histologie, diagnostic, symptômes, traitement et limites','Kystes médiastinaux, séries et cas','Revue américaine narrative, complément mécanismes/risques confronté aux sources européennes NVALT/France/Royaume-Uni ; pas fondement américain seul. Pas copie des figures sous licence sans dérivation.','Congénital souvent uniloculaire, acquis souvent multiloculaire sans équivalence absolue. Liquide protéique/hémorragique peut sembler solide au scanner. Ponction parfois non diagnostique et risque infection ; décision observation/chirurgie partagée si indétermination.')
add('S17','https://amiko.oddb.org/fr/fi?gtin=7680210370280','Néo-Mercazole comprimés5mg : information professionnelle suisse','Swissmedic/AIPS via AmiKo','Août2020, version servie2novembre2026','carbimazol.html','Formulation, indications, doses adultes/enfants, contre-indications, précautions, interactions, grossesse/allaitement, mécanisme','Hyperthyroïdie confirmée, pas indication thymique propre','Date de révision2020 explicitée, pas inventée2026. FI pas preuve d’effet thymique direct ni durée de régression. Produit non substitué mg pour mg au méthimazole.','Oral adulte20–60mg/j initial15–30jours en2–3prises puis5–20entretien titré. Dès12ans0,7–0,8mg/kg/j max60 ; moins12ans même plage initiale max30 et données très limitées. Fièvre/angine/aphtes : arrêter et consulter immédiatement/hémogramme. Hépatite/pancréatite, interactions coagulation, grossesse et allaitement détaillés.')
add('S18','https://openstax.org/books/anatomy-and-physiology-2e/pages/21-1-anatomy-of-the-lymphatic-and-immune-systems','Anatomy of the Lymphatic and Immune Systems, thymus','OpenStax','2e, chapitre21, version servie2026','openstax-thymus.html','Section Thymus et comparaison organes lymphoïdes primaires/secondaires','Normal pédagogique','Manuel américain de science normale uniquement, pas guideline clinique. Pronostic de120ans et chiffres de sénescence non repris. Figure21.7 crédit tiers Michigan, non réutilisée faute licence propre clarifiée.','Thymus bilobé antérieur, capsule/septa/lobules, cortex riche en thymocytes et médulla moins dense. Il ne filtre pas la lymphe comme un ganglion.')
add('S19','https://pmc.ncbi.nlm.nih.gov/articles/PMC13062478/','From Development to Aging: Dynamic Roles of the Thymic Medulla in T Cell Biology','Michalaki, Sharjeel et Cowan, University College London','8avril2026','medulla2026.xml','Introduction ;2.1,2.3,2.4,3.1,3.4,3.6 ; résumé et limites de transposition','Biologie thymique humaine et surtout modèles murins','Sections réellement lues, non tout article. Observations murines ne deviennent pas critères humains ni traitements disponibles. Auto-immunité non supprimée absolument par sélection.','Sélection positive, migration puis sélection négative et lymphocytes régulateurs ; présentation antigénique épithéliale/dendritique, AIRE, signaux de cytokines, involution et réparation distinctes de simple volume. Circuits régénératifs expérimentaux, pas indication clinique de régénérer un thymus.')
add('S20','https://smifk-cims.ch/download_file/view/c28daec4-78b0-4a6e-a198-00ca757191fc/261','PROFILES, situations de départ','CIMS Suisse','2017','/workspace/medina-source-cache/C85/profiles2017-official.pdf','p27–29 : usage des situations ;SSP2,4,6,37,44–49 ; nouvelle lecture ciblée2novembre2026','Formation médicale suisse','Pas correspondance officielle CIM-E32/examen. Les astérisques nosologiques historiques vers SSP156/184 ne sont pas adoptés comme mapping officiel.','Lymphadénopathie, fatigue, fièvre, douleur thoracique, toux, dyspnée, dysphagie et stridor sont des portes d’entrée au raisonnement ; intégrer contexte et urgence.')
